package com.memobell.app;
import android.app.*;import android.content.*;import android.os.*;
public class ReminderReceiver extends BroadcastReceiver {
 @Override public void onReceive(Context c,Intent i){String s=i.getStringExtra("text");if(s==null)s="You have a reminder";int id=i.getIntExtra("id",1);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"reminders"):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("MemoBell reminder").setContentText(s).setStyle(new Notification.BigTextStyle().bigText(s)).setAutoCancel(true);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(id,b.build());if(i.getBooleanExtra("daily",false)){Intent again=new Intent(c,ReminderReceiver.class);again.putExtra("id",id);again.putExtra("text",s);again.putExtra("daily",true);PendingIntent pi=PendingIntent.getBroadcast(c,id,again,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,System.currentTimeMillis()+86400000L,pi);} }
}
